const loadFont = makeLoadFont('Inter');

// Load Google Font at module level
const { fontFamily } = loadFont();

// 12x12 Pixel Art Rendering Component
const PixelArt: React.FC<{ type: "roblox" | "cyber" | "cat" | "trophy" }> = ({ type }) => {
  let art: string[] = [];
  const colorMap: Record<string, string> = {};

  if (type === "roblox") {
    art = [
      "....HHHH....",
      "...HHHHHH...",
      "...HFFFHF...",
      "...HFFFFH...",
      "...FFFFFF...",
      "..JJJSSJJJ..",
      "..JJJSSJJJ..",
      "..JJJSSJJJ..",
      "...PPPPPP...",
      "...PPPPPP...",
      "...WW..WW...",
      "...WW..WW..."
    ];
    colorMap["."] = "transparent";
    colorMap["H"] = "#8b5a2b"; // Hair
    colorMap["F"] = "#ffdbac"; // Skin peach
    colorMap["J"] = "#1e1e1e"; // Jacket
    colorMap["S"] = "#00bcd4"; // Cyan shirt
    colorMap["P"] = "#2c3e50"; // Pants
    colorMap["W"] = "#ffffff"; // Shoes
  } else if (type === "cyber") {
    art = [
      "....GGGG....",
      "...GGWWGG...",
      "..GGWWWWGG..",
      ".GGWWWWWWGG.",
      "GGWWWWWWWWGG",
      "GGWWWWWWWWGG",
      "GGWWWWWWWWGG",
      ".GGWWWWWWGG.",
      "..GGWWWWGG..",
      "...GGWWGG...",
      "....GGGG....",
      "............"
    ];
    colorMap["."] = "transparent";
    colorMap["G"] = "#00ffcc"; // Neon turquoise
    colorMap["W"] = "#111111"; // Inner dark depth
  } else if (type === "cat") {
    art = [
      "B..........B",
      "BB........BB",
      "BBB......BBB",
      "BBBBBBBBBBBB",
      "BWWBBBBBBWWB",
      "WWKWWBBWWKWW",
      "WWWWWWWWWWWW",
      "WWWWWWWWWWWW",
      ".WWWWPWWWWW.",
      "..WWWWWWWW..",
      "...WWWWWW...",
      "............"
    ];
    colorMap["."] = "transparent";
    colorMap["B"] = "#8e8e93"; // Grey cat accents
    colorMap["W"] = "#e5e5ea"; // White fur
    colorMap["K"] = "#000000"; // Eyes
    colorMap["P"] = "#ff2d55"; // Pink nose
  } else {
    // Golden Star / Trophy
    art = [
      ".....GG.....",
      "....GGGG....",
      "....GGGG....",
      "GGGGGGGGGGGG",
      ".GGGGGGGGGG.",
      "..GGGGGGGG..",
      "...GGGGGG...",
      "...GGGGGG...",
      "..GGGGGGGG..",
      ".GGGGGGGGGG.",
      "GGGGGGGGGGGG",
      "............"
    ];
    colorMap["."] = "transparent";
    colorMap["G"] = "#ffd700"; // Gold
  }

  return (
    <div
      style={{
        display: "grid",
        gridTemplateColumns: "repeat(12, 1fr)",
        gridTemplateRows: "repeat(12, 1fr)",
        width: "100%",
        height: "100%",
        gap: "2px",
        padding: "16px",
        boxSizing: "border-box",
      }}
    >
      {art.flatMap((row, rIdx) =>
        row.split("").map((char, cIdx) => (
          <div
            key={`${rIdx}-${cIdx}`}
            style={{
              backgroundColor: colorMap[char] || "transparent",
              borderRadius: "2px",
              boxShadow: char !== "." && type === "cyber" ? "0 0 10px rgba(0, 255, 204, 0.6)" : "none",
            }}
          />
        ))
      )}
    </div>
  );
};

interface NicheCardProps {
  title: string;
  numberText: string;
  numberColor: string;
  type: "roblox" | "cyber" | "cat" | "trophy";
  diff: number;
  scale: number;
  opacity: number;
  tilt: number;
  cardWidth: number;
  cardHeight: number;
}

// Single Card Component (Renders card + its highly realistic floor reflection)
const NicheCard: React.FC<NicheCardProps> = ({
  title,
  numberText,
  numberColor,
  type,
  diff,
  scale,
  opacity,
  tilt,
  cardWidth,
  cardHeight,
}) => {
  const activeProgress = Math.max(0, 1 - Math.abs(diff));
  
  const borderCol = activeProgress > 0.5 
    ? `rgba(255, 255, 255, ${0.15 + 0.6 * activeProgress})`
    : "rgba(255, 255, 255, 0.15)";
    
  const cardGlow = activeProgress > 0.5
    ? `0 0 40px rgba(255, 255, 255, ${0.15 * activeProgress})`
    : "none";

  const renderCardContent = (isReflection: boolean) => (
    <div
      style={{
        width: "100%",
        height: "100%",
        borderRadius: Math.min(cardWidth, cardHeight) * 0.08,
        border: `2px solid ${isReflection ? "rgba(255, 255, 255, 0.08)" : borderCol}`,
        background: "linear-gradient(180deg, rgba(20, 20, 20, 0.85) 0%, rgba(10, 10, 10, 0.95) 100%)",
        boxShadow: isReflection ? "none" : cardGlow,
        display: "flex",
        flexDirection: "column",
        overflow: "hidden",
        position: "relative",
        transition: "none",
      }}
    >
      {/* Glossy top-down glass shine overlay */}
      <div
        style={{
          position: "absolute",
          top: 0,
          left: 0,
          right: 0,
          height: "45%",
          background: "linear-gradient(185deg, rgba(255, 255, 255, 0.08) 0%, rgba(255, 255, 255, 0) 100%)",
          pointerEvents: "none",
          transition: "none",
        }}
      />

      {/* Header Container */}
      <div
        style={{
          padding: `${cardHeight * 0.07}px ${cardWidth * 0.08}px`,
          display: "flex",
          justifyContent: "flex-start",
          alignItems: "baseline",
          gap: "8px",
          transition: "none",
        }}
      >
        <span
          style={{
            color: "#ffffff",
            fontSize: cardHeight * 0.075,
            fontWeight: 800,
            letterSpacing: "-0.5px",
            textTransform: "uppercase",
            transition: "none",
          }}
        >
          {title}
        </span>
        <span
          style={{
            color: numberColor,
            fontSize: cardHeight * 0.075,
            fontWeight: 900,
            letterSpacing: "0.5px",
            transition: "none",
          }}
        >
          {numberText}
        </span>
      </div>

      {/* Graphic/Illustration Area */}
      <div
        style={{
          flex: 1,
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          position: "relative",
          margin: "0 14px 14px 14px",
          borderRadius: Math.min(cardWidth, cardHeight) * 0.04,
          backgroundColor: "rgba(0, 0, 0, 0.45)",
          border: "1px solid rgba(255, 255, 255, 0.05)",
          overflow: "hidden",
          transition: "none",
        }}
      >
        <PixelArt type={type} />
      </div>
    </div>
  );

  return (
    <>
      {/* Real Front Card */}
      <div
        style={{
          position: "absolute",
          width: cardWidth,
          height: cardHeight,
          left: 0,
          top: 0,
          opacity: opacity,
          transform: `perspective(1200px) rotateY(${tilt}deg) scale(${scale})`,
          transformOrigin: "center center",
          zIndex: Math.round(100 - Math.abs(diff) * 10),
          transition: "none",
        }}
      >
        {renderCardContent(false)}
      </div>

      {/* Glossy Floor Reflection */}
      <div
        style={{
          position: "absolute",
          width: cardWidth,
          height: cardHeight,
          left: 0,
          top: cardHeight * 1.04,
          opacity: opacity * 0.28 * (1 - Math.abs(diff) * 0.25),
          transform: `perspective(1200px) scaleY(-1) rotateY(${tilt}deg) scale(${scale})`,
          transformOrigin: "center top",
          zIndex: Math.round(50 - Math.abs(diff) * 10),
          transition: "none",
          pointerEvents: "none",
        }}
      >
        {renderCardContent(true)}
        {/* Reflection fading dark overlay gradient */}
        <div
          style={{
            position: "absolute",
            inset: 0,
            background: "linear-gradient(to top, rgba(10, 10, 10, 1) 0%, rgba(10, 10, 10, 0.1) 85%)",
            transition: "none",
          }}
        />
      </div>
    </>
  );
};

