export type SlidingCarouselProps = Record<string, any>;

const SlidingCarousel: React.FC<SlidingCarouselProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 12,
  cardSpacing = 430,
  activeScale = 1.15,
  tiltIntensity = 11,
  scrollSpeed = 1.0,
  cards = [
    { id: "1", title: "NICHE", numberText: "#1", numberColor: "#ff9800", type: "roblox" },
    { id: "2", title: "NICHE", numberText: "#2", numberColor: "#00bcd4", type: "cyber" },
    { id: "3", title: "NICHE", numberText: "#3", numberColor: "#e5e5ea", type: "cat" },
    { id: "4", title: "NICHE", numberText: "#4", numberColor: "#ffd700", type: "trophy" },
    { id: "5", title: "NICHE", numberText: "#5", numberColor: "#9c27b0", type: "roblox" },
    { id: "6", title: "NICHE", numberText: "#6", numberColor: "#00ffcc", type: "cyber" },
    { id: "7", title: "NICHE", numberText: "#7", numberColor: "#ff2d55", type: "cat" },
    { id: "8", title: "NICHE", numberText: "#8", numberColor: "#ffd700", type: "trophy" },
  ],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Intro entry spring animation
  const introProgress = spring({
    frame,
    fps,
    config: { damping: 14, stiffness: 85 },
  });

  // Calculate dynamic continuous center index for horizontal sliding
  const numCards = cards.length;
  const introRatio = 0.08; // first 8% of timeline dedicated to intro build
  const remainingRatio = 1.0 - introRatio;
  const carouselProgress = Math.max(0, (frame / (durationInSeconds * fps)) - introRatio) / remainingRatio;

  // Apply customizable scroll speed multiplier
  const adjustedProgress = Math.min(1, carouselProgress * scrollSpeed);

  // Apply Easing (slow -> fast -> slow) smoothly across the entire slide track
  const smoothProgress = Easing.bezier(0.42, 0, 0.58, 1)(adjustedProgress);
  const activeIndexProgress = smoothProgress * (numCards - 1);

  // Background and spotlight calculation
  const bgColor = transparentBackground ? "transparent" : backgroundColor;

  // Dynamic spotlight color that morphs based on the active card's index color
  const glowColor = interpolateColors(
    activeIndexProgress,
    cards.map((_, i) => i),
    cards.map((c) => c.numberColor)
  );

  // Offset background spotlight position horizontally as we navigate
  const spotlightX = 50 + (activeIndexProgress - (numCards - 1) / 2) * 6;
  const radialGlow = `radial-gradient(circle at ${spotlightX}% 40%, ${glowColor}1f 0%, ${bgColor} 72%)`;

  return (
    <AbsoluteFill
      style={{
        backgroundColor: bgColor,
        backgroundImage: radialGlow,
        fontFamily,
        overflow: "hidden",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
      }}
    >
      {/* Studio Floor Line / Horizon divider */}
      <div
        style={{
          position: "absolute",
          top: height * 0.70,
          left: 0,
          right: 0,
          height: height * 0.30,
          background: "linear-gradient(180deg, rgba(255, 255, 255, 0.015) 0%, rgba(255, 255, 255, 0) 100%)",
          borderTop: "1px solid rgba(255, 255, 255, 0.04)",
          pointerEvents: "none",
          zIndex: 5,
          transition: "none",
        }}
      />

      {/* Cards Sliding Track */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          overflow: "visible",
          pointerEvents: "none",
          transition: "none",
        }}
      >
        {cards.map((card, idx) => {
          const diff = idx - activeIndexProgress;
          const x = width / 2 + diff * cardSpacing;
          
          // Elevate active card slightly for a 3D staggered presentation
          const activeFactor = Math.max(0, 1 - Math.abs(diff));
          const verticalElevation = activeFactor * height * 0.035;
          const targetY = height * 0.43 - verticalElevation;
          const initialY = height * 1.35; // Fly in from below
          
          const y = interpolate(introProgress, [0, 1], [initialY, targetY]);

          // Combine entry spring scale with center proximity scale
          const computedScale = 1 + (activeScale - 1) * activeFactor;
          const scale = interpolate(introProgress, [0, 1], [0, computedScale]);

          // Fade out off-screen cards smoothly
          const baseOpacity = interpolate(Math.abs(diff), [1.8, 2.4], [1.0, 0.0], {
            extrapolateLeft: "clamp",
            extrapolateRight: "clamp",
          });
          const opacity = interpolate(introProgress, [0, 1], [0, baseOpacity]);
          const tilt = diff * -tiltIntensity;

          return (
            <div
              key={card.id}
              style={{
                position: "absolute",
                left: x,
                top: y,
                width: width * 0.22,
                height: height * 0.52,
                transform: "translate(-50%, -50%)",
                overflow: "visible",
                transition: "none",
              }}
            >
              <NicheCard
                title={card.title}
                numberText={card.numberText}
                numberColor={card.numberColor}
                type={card.type}
                diff={diff}
                scale={scale}
                opacity={opacity}
                tilt={tilt}
                cardWidth={width * 0.22}
                cardHeight={height * 0.52}
              />
            </div>
          );
        })}
      </div>
    </AbsoluteFill>
  );
};

export default SlidingCarousel;